<?php
$playlists = rows('SELECT idplaylist, nombre, imagen FROM playlist WHERE idusuario = ? ORDER BY idplaylist DESC', 'i', [$user['idusuario']]);
$libraryIds = array_column(rows('SELECT idcancion FROM biblioteca_tiene_cancion WHERE idbiblioteca = ?', 'i', [$user['idbiblioteca']]), 'idcancion');
$allSongs = catalogue();
$artists = rows('SELECT idartista, nombre, imagen FROM artista ORDER BY idartista');
function song_button(array $song, string $extra = ''): string {
    return '<button type="button" class="songItem ' . e($extra) . '" data-song="' . (int)$song['id'] . '"><img src="' . e($song['poster']) . '" alt=""><span><strong>' . e($song['name']) . '</strong><small>' . e($song['artist']) . '</small></span><span class="play-mark" aria-hidden="true">▶</span></button>';
}
?>
