<?php foreach ($playlists as $list): ?><a class="playlist-link" href="playlist_pagina.php?id=<?= (int)$list['idplaylist'] ?>"><img src="<?= $list['imagen'] === '' ? 'img/playlist.svg' : 'cover.php?id=' . (int)$list['idplaylist'] ?>" alt=""><span><?= e($list['nombre']) ?><small>Playlist</small></span></a><?php endforeach; ?>
