<section class="hero"><p class="eyebrow">DALE AL PLAY</p><h1><?= e($pageTitle) ?></h1><p><?= e($pageSubtitle) ?></p><?php if ($visibleSongs): ?><button class="primary" type="button" data-song="<?= (int)$visibleSongs[0]['id'] ?>">▶ Escuchar</button><?php endif; ?><div class="hero-orbit" aria-hidden="true"></div></section>
